PUSH_SCRIPT.msg:
(function() {{
	var ws = new WebSocket('{1}');
	ws.onopen = function(e) {{
		{2}.onOpen(e);
	};
	ws.onclose = function(e) {{
		{2}.onClose(e);
	};
	ws.onmessage = function(e) {{
		{2}.onMessage(e);
	};
	ws.onerror = function(e) {{
		{2}.onError(e);
	};
	return ws;
})();
